import{X as e,Y as t,ct as n,t as r}from"./chunks/framework.CaFWb3SA.js";var i=JSON.parse(`{"title":"Emuera 扩展语法","description":"","frontmatter":{},"headers":[],"relativePath":"translation/General.md","filePath":"translation/General.md"}`),a={name:`translation/General.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="emuera-扩展语法" tabindex="-1">Emuera 扩展语法 <a class="header-anchor" href="#emuera-扩展语法" aria-label="Permalink to “Emuera 扩展语法”">​</a></h1><blockquote><p>翻译自原文档：<a href="https://osdn.net/projects/emuera/wiki/exetc" target="_blank" rel="noreferrer">https://osdn.net/projects/emuera/wiki/exetc</a></p></blockquote><h2 id="行末注释" tabindex="-1">行末注释 <a class="header-anchor" href="#行末注释" aria-label="Permalink to “行末注释”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> B</span><span style="color:#6A9955;"> ;将 B 赋值给 A</span></span></code></pre></div><p>Emuera 允许在行的末尾插入注释。</p><p>但 <code>PRINT</code> 系指令是例外：由于 <code>PRINT</code> 指令的参数是一段文本，注释文本会被视作参数的一部分。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">PRINT</span><span style="color:#9CDCFE;"> foobar</span><span style="color:#6A9955;">	;一种播放器</span></span></code></pre></div><p>这种情况下会输出 <code>foobar ;一种播放器</code>。</p><h2 id="行连接" tabindex="-1">行连接 <a class="header-anchor" href="#行连接" aria-label="Permalink to “行连接”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">{</span></span>
<span class="line"><span style="color:#D4D4D4;">  #</span><span style="color:#9CDCFE;">DIM</span><span style="color:#9CDCFE;"> CONST</span><span style="color:#9CDCFE;"> HOGE</span><span style="color:#D4D4D4;"> =</span></span>
<span class="line"><span style="color:#B5CEA8;">    1</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">3</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">4</span></span>
<span class="line"><span style="color:#569CD6;">}</span></span></code></pre></div><p>上面的代码会被解释为 <code>#DIM CONST HOGE = 1,2,3,4</code>。</p><ul><li><code>{</code> 与 <code>}</code> 必须单独成行，除空白以外不能包含其他字符。</li><li>换行符所在的位置会被补上一个半角空格。也就是说，不能在函数名或变量名的中间断行；如果把 <code>PRINT</code> 等指令拆行，换行处的半角空格也会进入显示字符串。</li><li>Emuera 在语法解释上，会先进行行连接处理，再解释注释。</li></ul><p>也就是说：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">{</span></span>
<span class="line"><span style="color:#D4D4D4;">  #</span><span style="color:#9CDCFE;">DIM</span><span style="color:#9CDCFE;"> CONST</span><span style="color:#9CDCFE;"> HOGE</span><span style="color:#D4D4D4;"> =</span></span>
<span class="line"><span style="color:#B5CEA8;">    1</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">3</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">4</span><span style="color:#6A9955;"> ;注释</span></span>
<span class="line"><span style="color:#E6E6E6;">    ,</span><span style="color:#B5CEA8;">5</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">6</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">7</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">8</span></span>
<span class="line"><span style="color:#569CD6;">}</span></span></code></pre></div><p>会变成 <code>#DIM CONST HOGE = 1,2,3,4 ;注释 ,5,6,7,8</code>，其中 <code>,5,6,7,8</code> 会被视为行末注释的一部分而忽略。</p><h2 id="特殊注释行" tabindex="-1">特殊注释行 <a class="header-anchor" href="#特殊注释行" aria-label="Permalink to “特殊注释行”">​</a></h2><h3 id="" tabindex="-1">;!; <a class="header-anchor" href="#" aria-label="Permalink to “;!;”">​</a></h3><p>Emuera 和 Eramaker 都会把以 <code>;</code> 开头的行视为注释行，但 Emuera 会把以 <code>;!;</code> 开头的行视为有效行，而不是注释。</p><p>可以用它来书写不希望在 Eramaker 中执行的语句。</p><p>例如，在 <code>@SHOWSHOP</code> 中加入以下脚本，就可以禁止在 Emuera 中运行：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">;!;PRINTW</span><span style="color:#9CDCFE;"> 这个脚本不能在</span><span style="color:#9CDCFE;"> Emuera</span><span style="color:#9CDCFE;"> 上运行</span></span>
<span class="line"><span style="color:#569CD6;">;!;QUIT</span></span></code></pre></div><p>另外，与 <code>[SKIPSTART]</code>、<code>[SKIPEND]</code> 一起使用时，还可以像下面这样禁止在 Emuera 以外的环境中运行。在书写只希望 Emuera 执行的语句时可以使用：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">;!;</span><span style="color:#569CD6;">[</span><span style="color:#C586C0;">SKIPSTART</span><span style="color:#569CD6;">]</span></span>
<span class="line"><span style="color:#6A9955;">PRINTW 这个脚本只能在 Emuera 上运行</span></span>
<span class="line"><span style="color:#6A9955;">QUIT</span></span>
<span class="line"><span style="color:#6A9955;">;!;</span><span style="color:#569CD6;">[</span><span style="color:#C586C0;">SKIPEND</span><span style="color:#569CD6;">]</span></span></code></pre></div><h3 id="-1" tabindex="-1">;#; <a class="header-anchor" href="#-1" aria-label="Permalink to “;#;”">​</a></h3><p>以 <code>;#;</code> 开头的行只在调试模式下执行。</p><p>在非调试模式下，它会被视为注释行，不会被执行。</p><p>不过，<code>DEBUG</code> 系指令在非调试模式下原本就会被忽略，因此没有必要给这些行加上 <code>;#;</code>。同样，调试变量在非调试模式下是空字符串或 0，所以不必担心出错。</p><p>关于调试模式的详情，请参阅<a href="./Debug_Mode.html">调试模式</a>。</p><h2 id="角色-csv" tabindex="-1">角色 CSV <a class="header-anchor" href="#角色-csv" aria-label="Permalink to “角色 CSV”">​</a></h2><p>Eramaker 大概只准备了 100 个用于创建角色的数组。</p><p>因此，即使在 <code>chara3.csv</code>、<code>chara03.csv</code>、<code>chara3B.csv</code> 中定义了不同的角色，也只有其中一个有效。</p><p>在 Emuera 中，只要内存允许，就可以定义任意多个角色。</p><p>另外，只要符合 <code>chara*.csv</code> 的命名，像 <code>chara101.csv</code>、<code>charaABC.csv</code> 这样的文件也会被读取。</p><p>如果角色编号重复，<code>ADDCHARA</code> 或 <code>ADDSPCHARA</code> 存在多个候选项时，只有最先读取到的那个有效。</p><h2 id="整数类型的数值范围" tabindex="-1">整数类型的数值范围 <a class="header-anchor" href="#整数类型的数值范围" aria-label="Permalink to “整数类型的数值范围”">​</a></h2><p>Eramaker 能处理的整数是 32 位有符号整数，即 -2147483648 到 2147483647 的范围。</p><p>Emuera 与吉里吉里一样，能处理 64 位有符号整数，即 -9223372036854775808 到 9223372036854775807 的范围。</p><h2 id="对数组变量的批量赋值" tabindex="-1">对数组变量的批量赋值 <a class="header-anchor" href="#对数组变量的批量赋值" aria-label="Permalink to “对数组变量的批量赋值”">​</a></h2><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">10</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">3</span></span>
<span class="line"><span style="color:#9CDCFE;">DA</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">,</span><span style="color:#B5CEA8;">3</span></span></code></pre></div><p>如上书写时，<code>A:10</code> 到 <code>A:12</code> 会被分别赋值为 <code>1</code>、<code>2</code>、<code>3</code>。</p><p>对于多维数组，<code>DA:0:0</code> 到 <code>DA:0:2</code> 会被分别赋值为 <code>1</code>、<code>2</code>、<code>3</code>。</p><p>从 <code>DA:0:0</code> 到 <code>DA:0:99</code> 之后并不会继续对 <code>DA:1:0</code> 赋值，因此会发生数组越界引用错误。</p><p>另外，它不能用于复合赋值（不允许 <code>A += 1,2,3</code> 这样的写法）。</p><p>对字符串型数组变量进行批量赋值时，必须使用字符串赋值（<code>&#39;=</code>）。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;把「草莓,蜜瓜,蓝色夏威夷」这个字符串赋值给 STR:20</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">20</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> 草莓</span><span style="color:#E6E6E6;">,</span><span style="color:#9CDCFE;">蜜瓜</span><span style="color:#E6E6E6;">,</span><span style="color:#9CDCFE;">蓝色夏威夷</span></span>
<span class="line"><span style="color:#6A9955;">;把「草莓」「蜜瓜」「蓝色夏威夷」分别赋值给 STR:20～STR:22</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">20</span><span style="color:#D4D4D4;"> &#39;=</span><span style="color:#CE9178;"> &quot;草莓&quot;</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;蜜瓜&quot;</span><span style="color:#E6E6E6;">, </span><span style="color:#CE9178;">&quot;蓝色夏威夷&quot;</span></span></code></pre></div><h2 id="使用-form-语法为字符串变量赋值" tabindex="-1">使用 FORM 语法为字符串变量赋值 <a class="header-anchor" href="#使用-form-语法为字符串变量赋值" aria-label="Permalink to “使用 FORM 语法为字符串变量赋值”">​</a></h2><p>为字符串变量赋值时，可以直接使用带 FORM 语法的文本。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">SAVESTR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#569CD6;"> %</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#569CD6;">%</span></span></code></pre></div><p>这条语句会把 <code>RESULTS</code> 的值赋值给 <code>SAVESTR:0</code>。</p><p>在 Eramaker 中，同一条语句会把 <code>%RESULTS%</code> 这个字面文本本身赋值给 <code>SAVESTR:0</code>。</p><p>如果你希望在 Emuera 中赋值 <code>%RESULTS%</code> 这个字面文本本身，需要像下面这样转义：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">SAVESTR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#D7BA7D;"> \\%</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D7BA7D;">\\%</span></span></code></pre></div><p>紧跟在 <code>\\</code> 之后的字符不会被当作系统符号处理。</p><p>如果想让 <code>\\</code> 符号本身包含在字符串中，请使用 <code>\\\\</code>。</p><p>在少数情况下，如果希望 Eramaker 和 Emuera 具有相同的行为，需要这样书写：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#569CD6;">;!;</span><span style="color:#9CDCFE;">SAVESTR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#D7BA7D;"> \\%</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D7BA7D;">\\%</span></span>
<span class="line"><span style="color:#569CD6;">;!;</span><span style="color:#569CD6;">[</span><span style="color:#C586C0;">SKIPSTART</span><span style="color:#569CD6;">]</span></span>
<span class="line"><span style="color:#6A9955;">SAVESTR:0 = %RESULTS%</span></span>
<span class="line"><span style="color:#6A9955;">;!;</span><span style="color:#569CD6;">[</span><span style="color:#C586C0;">SKIPEND</span><span style="color:#569CD6;">]</span></span></code></pre></div><h2 id="使用字符串表达式为字符串变量赋值" tabindex="-1">使用字符串表达式为字符串变量赋值 <a class="header-anchor" href="#使用字符串表达式为字符串变量赋值" aria-label="Permalink to “使用字符串表达式为字符串变量赋值”">​</a></h2><p>在 ver1813 之后的 Emuera 中，可以使用赋值运算符 <code>&#39;=</code> 和字符串表达式来为字符串变量赋值。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;等同于「STR = 暮雪」</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;"> &#39;=</span><span style="color:#CE9178;"> &quot;暮雪&quot;</span></span>
<span class="line"><span style="color:#6A9955;">;等同于「STR = %TSTR:0%非雪」</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;"> &#39;=</span><span style="color:#9CDCFE;"> TSTR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> +</span><span style="color:#CE9178;"> &quot;非雪&quot;</span></span></code></pre></div><h2 id="用字符串指定数组变量的元素" tabindex="-1">用字符串指定数组变量的元素 <a class="header-anchor" href="#用字符串指定数组变量的元素" aria-label="Permalink to “用字符串指定数组变量的元素”">​</a></h2><p>对于以下变量，可以通过在 <code>*.csv</code> 中定义的字符串来指定其参数。</p><p>关于 Emuera 新增变量的详情，请参阅<a href="./Variable.html">常量与变量</a>。</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>ITEM (item.csv)</span></span>
<span class="line"><span>ITEMSALES (item.csv)</span></span>
<span class="line"><span>LOSEBASE (base.csv)</span></span>
<span class="line"><span>BASE (base.csv)</span></span>
<span class="line"><span>MAXBASE (base.csv)</span></span>
<span class="line"><span>ABL (abl.csv)</span></span>
<span class="line"><span>TALENT (talent.csv)</span></span>
<span class="line"><span>EXP (exp.csv)</span></span>
<span class="line"><span>MARK (mark.csv)</span></span>
<span class="line"><span>RELATION (chara*.csv)</span></span>
<span class="line"><span>UP (palam.csv)</span></span>
<span class="line"><span>DOWN (palam.csv)</span></span>
<span class="line"><span>PALAM (palam.csv)</span></span>
<span class="line"><span>JUEL (palam.csv)</span></span>
<span class="line"><span>GOTJUEL (palam.csv)</span></span>
<span class="line"><span>STAIN (stain.csv)</span></span>
<span class="line"><span>SOURCE (source.csv)</span></span>
<span class="line"><span>EX (ex.csv)</span></span>
<span class="line"><span>NOWEX (ex.csv)</span></span>
<span class="line"><span>TEQUIP (tequip.csv)</span></span>
<span class="line"><span>EQUIP (equip.csv)</span></span>
<span class="line"><span>FLAG (flag.csv)</span></span>
<span class="line"><span>TFLAG (tflag.csv)</span></span>
<span class="line"><span>CFLAG (cflag.csv)</span></span>
<span class="line"><span>STR (strname.csv)</span></span>
<span class="line"><span>SAVESTR (savestr.csv)</span></span>
<span class="line"><span>;以下为 Emuera 新增的变量</span></span>
<span class="line"><span>ITEMPRICE (item.csv)</span></span>
<span class="line"><span>DOWNBASE (base.csv)</span></span>
<span class="line"><span>CUP (palam.csv)</span></span>
<span class="line"><span>CDOWN (palam.csv)</span></span>
<span class="line"><span>TCVAR (tcvar.csv)</span></span>
<span class="line"><span>TSTR (tstr.csv)</span></span>
<span class="line"><span>CSTR (cstr.csv)</span></span>
<span class="line"><span>CDFLAG (cdflag1.csv, cdflag2.csv)</span></span>
<span class="line"><span>GLOBAL (global.csv)</span></span>
<span class="line"><span>GLOBALS (globals.csv)</span></span></code></pre></div><p>例如，如果 <code>abl.csv</code> 中定义了 <code>2,技巧</code>，那么以下四行具有相同的含义：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">ABL</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">技巧</span><span style="color:#D4D4D4;"> +=</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#9CDCFE;">ABL</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">2</span><span style="color:#D4D4D4;"> +=</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#9CDCFE;">ABL</span><span style="color:#D4D4D4;">:</span><span style="color:#CE9178;">&quot;技巧&quot;</span><span style="color:#D4D4D4;"> +=</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#9CDCFE;">ABL</span><span style="color:#D4D4D4;">:</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">ABLNAME</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">2</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">+=</span><span style="color:#B5CEA8;"> 1</span></span></code></pre></div><p>对于 <code>RELATION</code>，可以指定 <code>NAME</code> 或 <code>CALLNAME</code>。</p><p>如果有多个同名的定义，则最先定义的那个会被引用。</p><p>例如，如果 <code>abl.csv</code> 中定义了 <code>2,技巧</code> 和 <code>4,技巧</code>，且 <code>2,技巧</code> 定义在更前面的行，那么 <code>ABL:技巧</code> 就会变成 <code>ABL:2</code>。</p><p>字符串也可以是表达式或变量。这种情况下，需要像下面这样加上 <code>()</code>：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">ABL</span><span style="color:#D4D4D4;">:</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">=</span><span style="color:#9CDCFE;"> ABL</span><span style="color:#D4D4D4;">:</span><span style="color:#E6E6E6;">(</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#E6E6E6;">) </span><span style="color:#D4D4D4;">+</span><span style="color:#B5CEA8;"> 1</span></span></code></pre></div><p>如果省略 <code>()</code>，当项目名与变量名相同时，会优先解释为变量。</p><p>例如，如果 <code>abl.csv</code> 中定义了 <code>0,ローター</code>：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">@</span><span style="color:#DCDCAA;">HOGE</span></span>
<span class="line"><span style="color:#569CD6;">#</span><span style="color:#C586C0;">DIM</span><span style="color:#9CDCFE;"> ローター</span><span style="color:#E6E6E6;">, </span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#9CDCFE;">ローター</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 1</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#569CD6;"> {</span><span style="color:#9CDCFE;">ABL</span><span style="color:#D4D4D4;">:</span><span style="color:#9CDCFE;">ローター</span><span style="color:#569CD6;">}</span></span></code></pre></div><p>这种情况下，它会被解释为第 1 个 <code>ABL</code>，而不是第 0 个 <code>ABL</code>。</p><p>同样地，当项目名是数字时，会优先按数字解释。</p><p>例如，如果 <code>abl.csv</code> 中定义了 <code>0,10</code>，那么引用 <code>ABL:10</code> 时不会被解释为第 0 个 <code>ABL</code>，而是第 10 个 <code>ABL</code>。</p><p>这也可以在 <code>chara*.csv</code> 的定义中使用。</p><p>例如，如果 <code>abl.csv</code> 中定义了 <code>2,技巧</code>，那么以下两行的含义相同：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>能力,2,2</span></span>
<span class="line"><span>能力,技巧,2</span></span></code></pre></div><p>但是，它不能用于<strong>相性（RELATION）</strong>。</p><p>这是因为在读取 <code>chara*.csv</code> 的阶段，系统还不知道角色名与编号（NO）之间的对应关系。</p><h2 id="格式化字符串-form-语法-的扩展" tabindex="-1">格式化字符串（FORM 语法）的扩展 <a class="header-anchor" href="#格式化字符串-form-语法-的扩展" aria-label="Permalink to “格式化字符串（FORM 语法）的扩展”">​</a></h2><p>在 <code>PRINTFORM</code> 等使用的格式化字符串中，可以指定 <code>{}</code> 和 <code>%%</code> 要显示的字符数。</p><p>格式为：</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#E6E6E6;">{</span><span style="color:#9CDCFE;">数值变量或表达式</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">显示位数</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">对齐方向（LEFT</span><span style="color:#9CDCFE;"> 或</span><span style="color:#9CDCFE;"> RIGHT）</span><span style="color:#E6E6E6;">}</span></span>
<span class="line"><span style="color:#D4D4D4;">%</span><span style="color:#9CDCFE;">字符串变量或字符串表达式</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">显示位数</span><span style="color:#E6E6E6;">, </span><span style="color:#9CDCFE;">对齐方向（LEFT</span><span style="color:#9CDCFE;"> 或</span><span style="color:#9CDCFE;"> RIGHT）</span><span style="color:#D4D4D4;">%</span></span></code></pre></div><p>全角（日文）字符按 2 个字符计算。</p><p>显示位数不足时会补上半角空格。</p><p>默认是右对齐，指定关键字 <code>LEFT</code> 后则为左对齐。</p><p>如果原本的位数大于指定的显示位数，则按原样显示。</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;"> =</span><span style="color:#B5CEA8;"> 123456</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> あいう</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">A</span><span style="color:#569CD6;">}</span><span style="color:#E6E6E6;">]</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;">,</span><span style="color:#B5CEA8;">10</span><span style="color:#569CD6;">}</span><span style="color:#E6E6E6;">]</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;">,</span><span style="color:#B5CEA8;">10</span><span style="color:#D4D4D4;">,</span><span style="color:#9CDCFE;">LEFT</span><span style="color:#569CD6;">}</span><span style="color:#E6E6E6;">]</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#569CD6;">%</span><span style="color:#E6E6E6;">]</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">,</span><span style="color:#B5CEA8;">10</span><span style="color:#569CD6;">%</span><span style="color:#E6E6E6;">]</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">,</span><span style="color:#B5CEA8;">10</span><span style="color:#D4D4D4;">,</span><span style="color:#9CDCFE;">LEFT</span><span style="color:#569CD6;">%</span><span style="color:#E6E6E6;">]</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">{</span><span style="color:#9CDCFE;">A</span><span style="color:#D4D4D4;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#569CD6;">}</span><span style="color:#E6E6E6;">]</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORML</span><span style="color:#E6E6E6;"> [</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;">,</span><span style="color:#B5CEA8;">2</span><span style="color:#569CD6;">%</span><span style="color:#E6E6E6;">]</span></span></code></pre></div><p>输出：</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span>[123456]</span></span>
<span class="line"><span>[    123456]</span></span>
<span class="line"><span>[123456    ]</span></span>
<span class="line"><span>[あいう]</span></span>
<span class="line"><span>[    あいう]</span></span>
<span class="line"><span>[あいう    ]</span></span>
<span class="line"><span>[123456]</span></span>
<span class="line"><span>[あいう]</span></span></code></pre></div><h2 id="在字符串表达式中使用格式化的字符串-form-语法" tabindex="-1">在字符串表达式中使用格式化的字符串（FORM 语法） <a class="header-anchor" href="#在字符串表达式中使用格式化的字符串-form-语法" aria-label="Permalink to “在字符串表达式中使用格式化的字符串（FORM 语法）”">​</a></h2><p>在字符串表达式中直接使用 FORM 语法（例如作为 <code>PRINTS</code> 的参数，或作为表达式内用户定义函数的参数）会导致错误。</p><p>因此，在字符串表达式中使用格式化字符串时，可以像在字符串表达式中使用字符串常量那样，用 <code>@&quot;～&quot;</code> 来书写。</p><p>如果 <code>@&quot;～&quot;</code> 中的字符串只是用 <code>\\@～\\@</code> 的三元运算符描述的，还可以省略 <code>@&quot;～&quot;</code>，直接写成 <code>\\@～\\@</code>。</p><div class="tip custom-block"><p class="custom-block-title">正确示例</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;赋值使用的是 FORM 语法</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> あいう</span></span>
<span class="line"><span style="color:#6A9955;">;加法右侧是字符串表达式</span></span>
<span class="line"><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D4D4D4;"> +=</span><span style="color:#9CDCFE;"> STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span></span>
<span class="line"><span style="color:#6A9955;">;在字符串表达式中使用字符串常量的例子</span></span>
<span class="line"><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D4D4D4;"> +=</span><span style="color:#CE9178;"> &quot;えお&quot;</span></span>
<span class="line"><span style="color:#6A9955;">;在字符串表达式中使用 FORM 语法的例子</span></span>
<span class="line"><span style="color:#569CD6;">PRINTS</span><span style="color:#CE9178;"> @&quot;</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#569CD6;">%</span><span style="color:#CE9178;">甲乙丙丁戊&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A9955;">;以下四行完全相同</span></span>
<span class="line"><span style="color:#569CD6;">PRINTS</span><span style="color:#9CDCFE;"> STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> +</span><span style="color:#CE9178;"> &quot;！&quot;</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORM</span><span style="color:#569CD6;"> %</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#569CD6;">%</span><span style="color:#E6E6E6;">！</span></span>
<span class="line"><span style="color:#569CD6;">PRINTS</span><span style="color:#CE9178;"> @&quot;</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#569CD6;">%</span><span style="color:#CE9178;">！&quot;</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORM</span><span style="color:#569CD6;"> %</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> + </span><span style="color:#CE9178;">&quot;！&quot;</span><span style="color:#569CD6;">%</span></span></code></pre></div></div><div class="danger custom-block"><p class="custom-block-title">错误示例</p><div class="language-erb"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">erb</span><pre class="shiki slack-dark" style="background-color:#222222;color:#E6E6E6;" tabindex="0" dir="ltr"><code><span class="line"><span style="color:#6A9955;">;内容会变成 RESULTS</span></span>
<span class="line"><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#D4D4D4;"> =</span><span style="color:#9CDCFE;"> RESULTS</span></span>
<span class="line"><span style="color:#6A9955;">;会出错</span></span>
<span class="line"><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D4D4D4;"> +=</span><span style="color:#9CDCFE;"> えお</span></span>
<span class="line"><span style="color:#6A9955;">;会出错</span></span>
<span class="line"><span style="color:#9CDCFE;">RESULTS</span><span style="color:#D4D4D4;"> +=</span><span style="color:#569CD6;"> %</span><span style="color:#9CDCFE;">STR</span><span style="color:#D4D4D4;">:</span><span style="color:#B5CEA8;">0</span><span style="color:#569CD6;">%</span></span>
<span class="line"><span style="color:#6A9955;">;会连同 &quot;@ 和 &quot; 一起显示出来</span></span>
<span class="line"><span style="color:#569CD6;">PRINTFORM</span><span style="color:#E6E6E6;"> @&quot;</span><span style="color:#569CD6;">%</span><span style="color:#9CDCFE;">RESULTS</span><span style="color:#569CD6;">%</span><span style="color:#E6E6E6;">甲乙丙丁戊&quot;</span></span></code></pre></div></div><h2 id="在-inputs-系指令中使用宏语法" tabindex="-1">在 INPUTS 系指令中使用宏语法 <a class="header-anchor" href="#在-inputs-系指令中使用宏语法" aria-label="Permalink to “在 INPUTS 系指令中使用宏语法”">​</a></h2><p><code>INPUTS</code> 等输入接收指令可以使用宏表达式。</p><p>宏的格式请参阅使用指南中的宏相关章节。</p><p>如果不使用宏语法，而想把 <code>(</code> <code>)</code> 当作简单的字符串使用，请用 <code>\\</code> 进行转义。</p>`,102)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};